{"content":[{"type":"text","text":"/**
 * Date-range helpers.
 */

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Number of whole days covered by the INCLUSIVE range [start, end].
 *
 * e.g. 2026-01-01 .. 2026-01-01 covers 1 day; 2026-01-01 .. 2026-01-03 covers 3.
 */
export function inclusiveDayCount(start: Date, end: Date): number {
  const ms = end.getTime() - start.getTime();
  return Math.floor(ms / MS_PER_DAY) + 1;
}

/** All YYYY-MM-DD dates in the inclusive range, in order. */
export function eachDay(start: Date, end: Date): string[] {
  const out: string[] = [];
  for (let t = start.getTime(); t <= end.getTime(); t += MS_PER_DAY) {
    out.push(new Date(t).toISOString().slice(0, 10));
  }
  return out;
}
"}]}

{"content":[{"type":"text","text":"import { test } from "node:test";
import assert from "node:assert/strict";

import { eachDay, inclusiveDayCount } from "../src/date-range.ts";

const d = (s: string): Date => new Date(`${s}T00:00:00Z`);

// Pre-existing coverage for behaviour UNRELATED to the off-by-one bug being
// fixed — it passes before and after the fix (PASS_TO_PASS in the instance
// definition). It ships in the repo (like a real SWE-bench base test suite) so
// the build workflow's guardrails phase sees a tested, maintained project.
test("eachDay still lists every inclusive day", () => {
  assert.deepEqual(eachDay(d("2026-01-01"), d("2026-01-03")), ["2026-01-01", "2026-01-02", "2026-01-03"]);
});

test("inclusiveDayCount includes the end day", () => {
  assert.equal(inclusiveDayCount(d("2026-01-01"), d("2026-01-01")), 1); // same day = 1
  assert.equal(inclusiveDayCount(d("2026-01-01"), d("2026-01-02")), 2); // 2 consecutive days
  assert.equal(inclusiveDayCount(d("2026-01-01"), d("2026-01-03")), 3); // 3 days
});
"}]}

